<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$vehicleId=input_int('id_kendaraan');$areaId=input_int('id_area');$pdo->beginTransaction();
 $v=$pdo->prepare('SELECT id_kendaraan,plat_nomor,jenis_kendaraan FROM tb_kendaraan WHERE id_kendaraan=? FOR UPDATE');$v->execute([$vehicleId]);$vehicle=$v->fetch();if(!$vehicle)throw new InvalidArgumentException('Kendaraan tidak ditemukan.');
 $cardStmt=$pdo->prepare("SELECT id_kartu FROM tb_kartu_parkir WHERE id_kendaraan=? AND status='aktif' LIMIT 1 FOR UPDATE");$cardStmt->execute([$vehicleId]);$activeCard=$cardStmt->fetch();if(!$activeCard)throw new InvalidArgumentException('Kendaraan ini belum memiliki kartu parkir aktif. Minta Admin menerbitkan kartu.');
 $dupe=$pdo->prepare("SELECT id_parkir FROM tb_transaksi WHERE id_kendaraan=? AND status='masuk' LIMIT 1 FOR UPDATE");$dupe->execute([$vehicleId]);if($dupe->fetch())throw new InvalidArgumentException('Kendaraan ini sudah tercatat sedang parkir.');
 $tar=$pdo->prepare('SELECT id_tarif,tarif_per_jam FROM tb_tarif WHERE jenis_kendaraan=? FOR UPDATE');$tar->execute([$vehicle['jenis_kendaraan']]);$tariff=$tar->fetch();if(!$tariff)throw new InvalidArgumentException('Tarif untuk jenis kendaraan ini belum disiapkan Admin.');
 $a=$pdo->prepare('SELECT id_area,nama_area,kapasitas,terisi FROM tb_area_parkir WHERE id_area=? FOR UPDATE');$a->execute([$areaId]);$area=$a->fetch();if(!$area)throw new InvalidArgumentException('Area parkir tidak ditemukan.');if((int)$area['terisi'] >= (int)$area['kapasitas'])throw new InvalidArgumentException('Area yang dipilih sudah penuh. Pilih area lain.');
 $ins=$pdo->prepare("INSERT INTO tb_transaksi(id_kartu,id_kendaraan,waktu_masuk,id_tarif,tarif_saat_masuk,status,id_user,id_area) VALUES(?,?,NOW(),?,?,'masuk',?,?)");$ins->execute([(int)$activeCard['id_kartu'],$vehicleId,$tariff['id_tarif'],$tariff['tarif_per_jam'],current_user()['id'],$areaId]);$id=(int)$pdo->lastInsertId();$up=$pdo->prepare('UPDATE tb_area_parkir SET terisi=terisi+1 WHERE id_area=? AND terisi<kapasitas');$up->execute([$areaId]);if($up->rowCount()!==1)throw new RuntimeException('Kapasitas berubah saat transaksi. Coba kembali.');$log=$pdo->prepare('INSERT INTO tb_log_aktivitas(id_user,aktivitas) VALUES(?,?)');$log->execute([current_user()['id'],'Kendaraan '.$vehicle['plat_nomor'].' masuk; transaksi #'.$id]);$pdo->commit();flash('success','Kendaraan masuk berhasil dicatat. Nomor transaksi #'.$id.'.');redirect('petugas/transaksi-masuk.php?success_id='.$id);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():'Transaksi masuk gagal. Periksa ketersediaan area dan coba kembali.';if(!($e instanceof InvalidArgumentException))error_log('[ParkirSTRD entry] '.$e->getMessage());}}
$vehicles=$pdo->query("SELECT k.id_kendaraan,k.plat_nomor,k.jenis_kendaraan,k.pemilik,c.id_kartu,c.kode_kartu FROM tb_kendaraan k JOIN tb_kartu_parkir c ON c.id_kendaraan=k.id_kendaraan AND c.status='aktif' WHERE NOT EXISTS(SELECT 1 FROM tb_transaksi t WHERE t.id_kendaraan=k.id_kendaraan AND t.status='masuk') ORDER BY k.plat_nomor")->fetchAll();$areas=$pdo->query('SELECT id_area,nama_area,kapasitas,terisi FROM tb_area_parkir ORDER BY nama_area')->fetchAll();$rates=[];foreach($pdo->query('SELECT jenis_kendaraan,tarif_per_jam FROM tb_tarif')->fetchAll() as $r)$rates[$r['jenis_kendaraan']]=$r['tarif_per_jam'];$successId=(int)($_GET['success_id']??0);$successRow=null;if($successId){$s=$pdo->prepare("SELECT t.id_parkir,k.plat_nomor,t.waktu_masuk,a.nama_area,t.tarif_saat_masuk,c.kode_kartu FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan JOIN tb_area_parkir a ON a.id_area=t.id_area LEFT JOIN tb_kartu_parkir c ON c.id_kartu=t.id_kartu WHERE t.id_parkir=? AND t.status='masuk'");$s->execute([$successId]);$successRow=$s->fetch()?:null;}render_header('Transaksi Kendaraan Masuk','masuk');?>
<div class="page-intro"><div><h2>Catat kendaraan masuk</h2><p>Sistem akan memeriksa transaksi ganda dan mengunci kapasitas area saat proses simpan.</p></div><div class="table-actions"><a class="btn btn-primary" href="<?= h(url('petugas/scanner.php')) ?>">Scan kartu barcode</a><a class="btn btn-secondary" href="<?= h(url('petugas/kendaraan-aktif.php')) ?>">Lihat kendaraan aktif</a></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><?php if($successRow): ?><section class="panel"><div class="panel-body"><div style="display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap"><div><span class="badge badge-success">Transaksi berhasil</span><h2 style="font:800 20px Manrope;margin:9px 0">#<?= (int)$successRow['id_parkir'] ?> · <?= h($successRow['plat_nomor']) ?></h2><p class="muted">Masuk <?= h(tanggal($successRow['waktu_masuk'])) ?> · <?= h($successRow['nama_area']) ?> · Snapshot tarif <?= h(rupiah($successRow['tarif_saat_masuk'])) ?>/jam</p><div class="barcode-wrap" style="margin-top:14px"><svg data-barcode="<?= h($successRow['kode_kartu'] ?: 'PARKIRSTRD-IN-'.$successRow['id_parkir']) ?>"></svg><span class="barcode-caption">Barcode kartu parkir · transaksi #<?= (int)$successRow['id_parkir'] ?></span></div></div><a class="btn btn-primary" href="<?= h(url('petugas/transaksi-keluar.php?id='.(int)$successRow['id_parkir'])) ?>">Proses saat keluar →</a></div></div></section><?php endif; ?><section class="panel"><div class="panel-heading"><div><h2>Form kendaraan masuk</h2><p>Pilih kendaraan terdaftar dan area yang memiliki slot tersedia.</p></div></div><form method="post" class="form-grid single-col"><?= csrf_field() ?><div class="field"><label>Kendaraan</label><select name="id_kendaraan" required><option value="">Pilih plat nomor...</option><?php foreach($vehicles as $v): ?><option value="<?= (int)$v['id_kendaraan'] ?>"><?= h($v['plat_nomor'].' · '.ucfirst($v['jenis_kendaraan']).' · '.$v['pemilik'].' · '.rupiah($rates[$v['jenis_kendaraan']]??0).'/jam') ?></option><?php endforeach; ?></select><?php if(!$vehicles): ?><small>Tidak ada kendaraan yang siap masuk. Pastikan kendaraan terdaftar dan memiliki kartu parkir aktif dari Admin.</small><?php endif; ?></div><div class="field"><label>Area parkir</label><select name="id_area" required><option value="">Pilih area parkir...</option><?php foreach($areas as $a): ?><option value="<?= (int)$a['id_area'] ?>" <?= (int)$a['terisi']>=(int)$a['kapasitas']?'disabled':'' ?>><?= h($a['nama_area'].' · '.max(0,(int)$a['kapasitas']-(int)$a['terisi']).' slot tersedia dari '.$a['kapasitas']) ?></option><?php endforeach; ?></select><?php if(!$areas): ?><small>Belum ada area. Minta Admin menambahkan area parkir.</small><?php endif; ?></div><div class="alert" style="background:#f4f8ff;color:#586c8a;margin:0">ℹ Waktu masuk memakai waktu server MySQL. Sistem menyimpan tarif saat masuk agar transaksi lama tidak berubah ketika tarif master diedit.</div><div class="form-actions"><button class="btn btn-primary" <?= (!$vehicles||!array_filter($areas,fn($a)=>(int)$a['terisi']<(int)$a['kapasitas']))?'disabled':'' ?>>Simpan kendaraan masuk</button></div></form></section><section class="panel"><div class="panel-heading"><div><h2>Kapasitas area</h2><p>Informasi slot terkini.</p></div></div><div class="table-wrap"><table><thead><tr><th>Area</th><th>Kapasitas</th><th>Terisi</th><th>Tersedia</th><th>Status</th></tr></thead><tbody><?php foreach($areas as $a):$free=(int)$a['kapasitas']-(int)$a['terisi'];?><tr><td class="td-main"><?= h($a['nama_area']) ?></td><td><?= (int)$a['kapasitas'] ?></td><td><?= (int)$a['terisi'] ?></td><td><?= $free ?></td><td><?= $free===0?'<span class="badge badge-danger">Penuh</span>':'<span class="badge badge-success">Tersedia</span>' ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php render_footer(); ?>